using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
namespace StudentHub.Data;
public sealed class StudentHubDbContext(DbContextOptions<StudentHubDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
 public DbSet<AcademicTerm> AcademicTerms => Set<AcademicTerm>(); public DbSet<Course> Courses => Set<Course>(); public DbSet<Assignment> Assignments => Set<Assignment>(); public DbSet<StudentDocument> Documents => Set<StudentDocument>(); public DbSet<Exam> Exams => Set<Exam>(); public DbSet<CourseGrade> CourseGrades => Set<CourseGrade>(); public DbSet<AppNotification> Notifications => Set<AppNotification>(); public DbSet<UserPreference> UserPreferences => Set<UserPreference>();
 protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);b.Entity<AcademicTerm>().Property(x=>x.Name).HasMaxLength(80).IsRequired();b.Entity<Course>().Property(x=>x.Code).HasMaxLength(24).IsRequired();b.Entity<Course>().Property(x=>x.Name).HasMaxLength(180).IsRequired();b.Entity<Course>().Property(x=>x.CreditHours).HasPrecision(5,2);b.Entity<CourseGrade>().Property(x=>x.GradePoint).HasPrecision(5,2);b.Entity<Assignment>().Property(x=>x.Name).HasMaxLength(180).IsRequired();b.Entity<StudentDocument>().Property(x=>x.OriginalFileName).HasMaxLength(255).IsRequired();}
}
public sealed class AcademicTerm { public int Id {get;set;} public string OwnerId {get;set;}=string.Empty; public string Name {get;set;}=string.Empty; public DateOnly? StartsOn {get;set;} public DateOnly? EndsOn {get;set;} }
public sealed class Course { public int Id {get;set;} public string OwnerId {get;set;}=string.Empty; public int TermId {get;set;} public string Code {get;set;}=string.Empty; public string Name {get;set;}=string.Empty; public decimal CreditHours {get;set;} }
public sealed class Assignment { public int Id {get;set;} public string OwnerId {get;set;}=string.Empty; public int CourseId {get;set;} public string Name {get;set;}=string.Empty; public DateTime DueAtUtc {get;set;} public string Priority {get;set;}="Medium"; public string Status {get;set;}="NotStarted"; }
public sealed class StudentDocument { public int Id {get;set;} public string OwnerId {get;set;}=string.Empty; public string OriginalFileName {get;set;}=string.Empty; public string StoredFileName {get;set;}=string.Empty; public string ContentType {get;set;}=string.Empty; public long SizeBytes {get;set;} public bool IsPublic {get;set;} public DateTime CreatedAtUtc {get;set;}=DateTime.UtcNow; }
public sealed class Exam { public int Id {get;set;} public string OwnerId {get;set;}=string.Empty; public int CourseId {get;set;} public string ExamType {get;set;}="Quiz"; public DateTime StartsAtUtc {get;set;} public string? Location {get;set;} public int? DurationMinutes {get;set;} public string? Notes {get;set;} public bool IsCompleted {get;set;} }
public sealed class CourseGrade { public int Id {get;set;} public string OwnerId {get;set;}=string.Empty; public int CourseId {get;set;} public string Letter {get;set;}=string.Empty; public decimal GradePoint {get;set;} public bool IsConfirmed {get;set;} }
public sealed class AppNotification { public int Id {get;set;} public string OwnerId {get;set;}=string.Empty; public string Title {get;set;}=string.Empty; public string Message {get;set;}=string.Empty; public string Category {get;set;}=string.Empty; public string Priority {get;set;}="Normal"; public bool IsRead {get;set;} public string? TargetUrl {get;set;} public DateTime CreatedAtUtc {get;set;}=DateTime.UtcNow; }
public sealed class UserPreference { public int Id {get;set;} public string OwnerId {get;set;}=string.Empty; public string Language {get;set;}="en"; public string Theme {get;set;}="system"; public bool AssignmentReminders {get;set;}=true; public bool ExamReminders {get;set;}=true; public bool CalendarReminders {get;set;}=true; public bool AcademicUpdates {get;set;}=true; }
